import 'package:flutter/material.dart';

class ErrorRecoveryPage extends StatelessWidget {
  const ErrorRecoveryPage({Key? key}) : super(key: key);

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: const Color(0xFFF8F9FA),
      body: SafeArea(
        child: Padding(
          padding: const EdgeInsets.all(24),
          child: Column(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              const Icon(Icons.error_outline, size: 64, color: Colors.red),
              const SizedBox(height: 16),
              const Text('Failed to load AI model',
                style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold),
                textAlign: TextAlign.center),
              const SizedBox(height: 8),
              const Text(
                'The Gemma model could not be initialized. Please re-download the model.',
                textAlign: TextAlign.center,
                style: TextStyle(color: Colors.grey)),
              const SizedBox(height: 32),
              Semantics(
                label: 'Go back to download page',
                button: true,
                child: ElevatedButton.icon(
                  onPressed: () => Navigator.of(context).popUntil((r) => r.isFirst),
                  icon: const Icon(Icons.download),
                  label: const Text('Re-download Model'),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_gemma/pigeon.g.dart';
import 'chat_page/config/system_prompts.dart';

class SettingsPage extends StatefulWidget {
  final String systemContext;
  final PreferredBackend backend;
  const SettingsPage({Key? key, required this.systemContext, required this.backend}) : super(key: key);
  @override
  State<SettingsPage> createState() => _SettingsPageState();
}

class _SettingsPageState extends State<SettingsPage> {
  late TextEditingController _promptController;
  late PreferredBackend _backend;

  @override
  void initState() {
    super.initState();
    _promptController = TextEditingController(text: widget.systemContext);
    _backend = widget.backend;
  }

  @override
  void dispose() { _promptController.dispose(); super.dispose(); }

